import csv, sys
from collections import defaultdict, deque

rows = list(csv.DictReader(open(sys.argv[1])))
by_id = {r["patient_id"]: r for r in rows}
out = {r["patient_id"]: r["emergency_contact_patient_id"] for r in rows}
inc = defaultdict(list)
for r in rows:
    inc[r["emergency_contact_patient_id"]].append(r["patient_id"])
adj = defaultdict(set)
for p, q in out.items():
    adj[p].add(q); adj[q].add(p)

def lab(p):
    r = by_id[p]
    c = f'${float(r["direct_payment_usd"]):.0f} {r["compensation_reason"]}' if r["record_date"] else "NO CLAIM"
    return f'{p} {r["full_name"]:18s} [{c}]'

BIG = ["PAT_033", "PAT_265", "PAT_006"]
for b in BIG:
    print("=" * 95)
    print("BIG:", lab(b), " surname:", by_id[b]["second_name"])
    dist = {b: 0}; q = deque([b])
    while q:
        u = q.popleft()
        if dist[u] >= 2: continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1; q.append(v)
    for d in (1, 2):
        print(f"  -- hop {d} --")
        for v in sorted(dist, key=lambda x: x):
            if dist[v] != d: continue
            rel = []
            if out.get(b) == v: rel.append("claimant's EC")
            if out.get(v) == b: rel.append("lists claimant as EC")
            if by_id[v]["second_name"] == by_id[b]["second_name"]: rel.append("SAME SURNAME")
            if not by_id[v]["record_date"]: rel.append("***NO CLAIM***")
            print(f"     {lab(v)}  {' | '.join(rel)}")

print("\n\n=== duplicate full names ===")
dup = defaultdict(list)
for r in rows: dup[r["full_name"]].append(r["patient_id"])
for n, ids in sorted(dup.items()):
    if len(ids) > 1: print(f"  {n:20s} {ids}")

print("\n=== mutual EC pairs ===")
for p, q in out.items():
    if out.get(q) == p and p < q: print(" ", lab(p), "<->", lab(q))
EOF
