import csv, sys
from collections import defaultdict, deque

rows = list(csv.DictReader(open(sys.argv[1])))
by_id = {r["patient_id"]: r for r in rows}
out = {r["patient_id"]: r["emergency_contact_patient_id"] for r in rows}
inc = defaultdict(list)
for r in rows: inc[r["emergency_contact_patient_id"]].append(r["patient_id"])
adj = defaultdict(set)
for p, q in out.items(): adj[p].add(q); adj[q].add(p)
noclaim = lambda p: not by_id[p]["record_date"]

def lab(p):
    r = by_id[p]
    c = f'${float(r["direct_payment_usd"]):.0f} {r["compensation_reason"]}' if r["record_date"] else "NO CLAIM"
    return f'{p} {r["full_name"]:18s} [{c}]'

print("### FULL 3-hop around PAT_006 Taylor Jones ###")
dist = {"PAT_006": 0}; q = deque(["PAT_006"])
while q:
    u = q.popleft()
    if dist[u] >= 3: continue
    for v in adj[u]:
        if v not in dist: dist[v] = dist[u]+1; q.append(v)
for d in range(1,4):
    print(f" -- hop {d} --")
    for v in [x for x in dist if dist[x]==d]:
        print("   ", lab(v), "NOCLAIM!!" if noclaim(v) else "")

print("\n### in-degree of NO-CLAIM patients (who is a hub but never filed) ###")
cand = sorted([p for p in by_id if noclaim(p)], key=lambda p: -len(inc[p]))
for p in cand[:15]:
    print(f"  indeg={len(inc[p])} {lab(p)}   listed-by: {[by_id[x]['full_name'] for x in inc[p]]}")

print("\n### record_date range per big claim vs others ###")
for r in sorted([r for r in rows if r['record_date']], key=lambda r: r['record_date']):
    if float(r['direct_payment_usd'])>60000: print("  BIG", r['record_date'], lab(r['patient_id']))
print("  date min/max:", min(r['record_date'] for r in rows if r['record_date']), max(r['record_date'] for r in rows if r['record_date']))

print("\n### inactive coverage / incomplete docs ###")
for r in rows:
    if r['record_date'] and (r['coverage_status']!='active' or r['documentation_status']!='complete'):
        print(f"   {lab(r['patient_id'])} cov={r['coverage_status']} doc={r['documentation_status']} ec->{lab(out[r['patient_id']])}")
EOF
