adj = defaultdict(set)
for p,q in out.items(): adj[p].add(q); adj[q].add(p)
noclaim = lambda p: not by_id[p]["record_date"]
BIG = {"PAT_033":"Rivera","PAT_265":"Quill","PAT_006":"Jones"}

def lab(p):
    r=by_id[p]
    c=f'${float(r["direct_payment_usd"]):.0f} {r["compensation_reason"]}' if r["record_date"] else "NO CLAIM"
    return f'{p} {r["full_name"]:18s} [{c}]'

# how unusual is PAT_006 having zero no-claim neighbors?
z=[p for p in by_id if by_id[p]["record_date"] and not any(noclaim(v) for v in adj[p])]
print(f"claimants with ZERO no-claim neighbours: {len(z)}/95")

print("\n### BFS distance from each BIG to every NO-CLAIM patient (dist<=4) ###")
for b,sur in BIG.items():
    dist={b:0}; q=deque([b])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if v not in dist: dist[v]=dist[u]+1; q.append(v)
    print(f"\n-- {lab(b)} (surname {sur}) --")
    nc=sorted([(d,p) for p,d in dist.items() if noclaim(p) and d<=4])
    for d,p in nc[:12]:
        s=" <<SAME SURNAME>>" if by_id[p]["second_name"]==sur else ""
        print(f"   d={d} {lab(p)}{s}")
    # same-surname no-claim anywhere
    print(f"   all no-claim {sur}s:", [(p, dist.get(p,'inf')) for p in by_id if noclaim(p) and by_id[p]['second_name']==sur])

print("\n### connected components ###")
seen=set(); comps=[]
for p in by_id:
    if p in seen: continue
    c=set(); q=deque([p]); c.add(p); seen.add(p)
    while q:
        u=q.popleft()
        for v in adj[u]:
            if v not in c: c.add(v); seen.add(v); q.append(v)
    comps.append(c)
print("sizes:", sorted(len(c) for c in comps))
for c in comps:
    bigs=[b for b in BIG if b in c]
    if bigs: print(f"  component size {len(c)} contains BIG {bigs}")
