import csv, sys
from collections import defaultdict

rows = list(csv.DictReader(open(sys.argv[1])))
by_id = {r["patient_id"]: r for r in rows}
out = {r["patient_id"]: r["emergency_contact_patient_id"] for r in rows}
inc = defaultdict(list)
for r in rows: inc[r["emergency_contact_patient_id"]].append(r["patient_id"])
nbr = lambda p: set([out[p]]) | set(inc[p])
noclaim = lambda p: not by_id[p]["record_date"]
BIG = ["PAT_033", "PAT_265", "PAT_006"]

def full(p):
    r = by_id[p]
    pay = f'${float(r["direct_payment_usd"]):>8.0f}' if r["record_date"] else '  NO CLAIM'
    return (f'{p} {r["full_name"]:16s} {pay} {r["compensation_reason"]:32s} '
            f'{r["record_date"]:10s} {r["policy_tier"]:8s} {r["coverage_status"]:8s} {r["documentation_status"]}')

for b in BIG:
    br = by_id[b]
    print("="*120)
    print("SURVIVOR CLAIM:", full(b))
    print(f"  direction: {b} --EC--> {out[b]}")
    for v in sorted(nbr(b)):
        marks=[]
        if out[b]==v: marks.append("claimant's EC")
        if out.get(v)==b: marks.append("names claimant as EC")
        if by_id[v]["second_name"]==br["second_name"]: marks.append("*** SAME SURNAME ***")
        if noclaim(v): marks.append("NO CLAIM")
        print("   ", full(v), "|", ", ".join(marks))

print("\n\n" + "="*120)
print("RULE TESTS (candidate deceased per survivor claim)")
rules = {
  "A: adjacent & same surname      ": lambda b: [v for v in nbr(b) if by_id[v]["second_name"]==by_id[b]["second_name"]],
  "B: adjacent & no claim          ": lambda b: [v for v in nbr(b) if noclaim(v)],
  "C: adjacent & surname & no claim": lambda b: [v for v in nbr(b) if noclaim(v) and by_id[v]["second_name"]==by_id[b]["second_name"]],
  "D: claimant's own EC            ": lambda b: [out[b]],
  "E: names claimant as EC         ": lambda b: list(inc[b]),
}
for name, f in rules.items():
    res = {b: f(b) for b in BIG}
    sizes = [len(v) for v in res.values()]
    ok = "UNIQUE & COMPLETE" if all(s==1 for s in sizes) else "incomplete/ambiguous"
    print(f"\n{name} -> {ok}")
    for b in BIG:
        print(f"    {b} ({by_id[b]['second_name']:7s}): {[(v, by_id[v]['full_name'], 'noclaim' if noclaim(v) else 'HAS CLAIM') for v in res[b]]}")
EOF
