import csv, sys
from collections import defaultdict, deque

rows = list(csv.DictReader(open(sys.argv[1])))
by_id = {r["patient_id"]: r for r in rows}
order = {r["patient_id"]: i for i, r in enumerate(rows)}
out = {r["patient_id"]: r["emergency_contact_patient_id"] for r in rows}
inc = defaultdict(list)
for r in rows: inc[r["emergency_contact_patient_id"]].append(r["patient_id"])
adj = defaultdict(set)
for p,q in out.items(): adj[p].add(q); adj[q].add(p)
noclaim = lambda p: not by_id[p]["record_date"]
pay = lambda p: float(by_id[p]["direct_payment_usd"]) if by_id[p]["record_date"] else 0.0
BIG = {"PAT_033":"bereavement", "PAT_265":"family support", "PAT_006":"life event"}

dists = {}
for b in BIG:
    d = {b:0}; q=deque([b])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if v not in d: d[v]=d[u]+1; q.append(v)
    dists[b]=d

print("### Ranking ALL no-claim patients ###")
cands=[]
for p in by_id:
    if not noclaim(p): continue
    adjbig = [b for b in BIG if b in adj[p]]
    surmatch = [b for b in BIG if by_id[b]["second_name"]==by_id[p]["second_name"]]
    mind = min(dists[b].get(p, 99) for b in BIG)
    nbrpay = sum(pay(v) for v in adj[p])
    score = 100*len(adjbig) + 30*len(surmatch) + (20 if any(b in adj[p] and by_id[b]['second_name']==by_id[p]['second_name'] for b in BIG) else 0) - mind
    cands.append((score, p, adjbig, surmatch, mind, nbrpay, len(inc[p])))
cands.sort(reverse=True)
print(f"{'score':>6} {'id':8} {'name':18} {'adj-to-BIG':26} {'surname-match':16} {'minD':>4} {'nbr$':>9} {'indeg':>5}")
for s,p,ab,sm,md,np_,ind in cands[:14]:
    print(f"{s:6.0f} {p:8} {by_id[p]['full_name']:18} {str([BIG[b] for b in ab]):26} {str([BIG[b] for b in sm]):16} {md:4} {np_:9.0f} {ind:5}")

print("\n### no-claim people whose EC is ALSO no-claim (chains of non-filers) ###")
for p in by_id:
    if noclaim(p) and noclaim(out[p]):
        print(f"   {p} {by_id[p]['full_name']:18} -> {out[p]} {by_id[out[p]]['full_name']}")

print("\n### row order positions ###")
for b in BIG: print(f"   BIG {b} at row {order[b]}")
for p in ["PAT_174","PAT_065","PAT_023","PAT_032","PAT_126"]:
    print(f"   cand {p} {by_id[p]['full_name']:18} at row {order[p]}")
EOF
